.tile-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 10px 8px;
  border-top: 1px solid var(--border);
  margin-top: 5px;
}
.drift-badge {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 4px;
}
.drift-badge.ok      { background: rgba(20,184,166,.15); color: var(--accent); }
.drift-badge.warn    { background: rgba(245,158,11,.15);  color: var(--warn);   }
.drift-badge.bad     { background: rgba(239,68,68,.15);   color: var(--danger); }
.drift-badge.flagged { background: rgba(239,68,68,.22);   color: var(--danger); }
 
.tile-actions { display: flex; gap: 4px; }
.btn-icon {
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 14px;
  padding: 2px 5px;
  border-radius: 4px;
  line-height: 1;
}
.btn-icon:hover  { color: var(--text); }
.btn-flag.active { color: var(--danger); }
 
/* ── ADD TILE ────────────────────────────────────────────────────────────── */
.btn-add-tile {
  grid-column: 1 / -1;
  background: none;
  border: 1px dashed var(--border);
  border-radius: 10px;
  color: var(--muted);
  cursor: pointer;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: .08em;
  padding: 14px;
  text-align: center;
  text-transform: uppercase;
  width: 100%;
  transition: border-color .15s, color .15s;
}
.btn-add-tile:hover { border-color: var(--accent); color: var(--accent); }
 
/* ── BOTTOM BAR ──────────────────────────────────────────────────────────── */
.bottom-bar {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  background: rgba(15,15,17,.93);
  backdrop-filter: blur(12px);
  border-top: 1px solid var(--border);
  padding: 10px 16px max(10px, env(safe-area-inset-bottom));
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 200;
}
.summary-line { flex: 1; }
.summary-line span {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .05em;
  color: var(--muted);
}
.summary-line .s-total { color: var(--text); font-weight: 700; }
.summary-line .s-bad   { color: var(--danger); }
.summary-line .s-warn  { color: var(--warn);   }
 
.btn-copy {
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: #000;
  cursor: pointer;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  padding: 10px 14px;
  text-transform: uppercase;
  transition: opacity .15s;
  white-space: nowrap;
}
.btn-copy:hover  { opacity: .85; }
.btn-copy:active { opacity: .7; }
 
/* ── TOAST ───────────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  bottom: 76px; left: 50%;
  transform: translateX(-50%) translateY(10px);
  background: var(--surf2);
  border: 1px solid var(--accent);
  border-radius: 8px;
  color: var(--accent);
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: .06em;
  padding: 8px 16px;
  pointer-events: none;
  opacity: 0;
  transition: opacity .2s, transform .2s;
  z-index: 300;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
</style>
</head>
<body>
 
<!-- ── HEADER ────────────────────────────────────────────────────────────── -->
<header class="site-header">
  <h1>⬡ Icon <span class="h1-accent">Consistency</span> Studio</h1>
  <details class="dna-panel" open id="dnaDetails">
    <summary>Family DNA</summary>
    <div class="dna-grid">
 
      <div>
        <label for="dna-shape">Shape language</label>
        <select id="dna-shape">
          <option>Rounded corners</option>
          <option>Sharp / geometric</option>
          <option>Organic / freeform</option>
          <option>Mixed</option>
        </select>
      </div>
 
      <div>
        <label for="dna-radius">Corner radius</label>
        <input type="text" id="dna-radius" placeholder="e.g. 4 px" value="8 px">
      </div>
 
      <div>
        <label for="dna-stroke">Stroke weight</label>
        <input type="text" id="dna-stroke" placeholder="e.g. 2 px" value="2 px">
      </div>
 
      <div>
        <label for="dna-fill">Fill style</label>
        <select id="dna-fill">
          <option>Outline / line</option>
          <option>Filled / solid</option>
          <option>Duotone</option>
          <option>Gradient</option>
          <option>Mixed</option>
        </select>
      </div>
 
      <div>
        <label for="dna-detail">Detail level</label>
        <select id="dna-detail">
          <option>Minimal (1–2 elements)</option>
          <option>Medium (3–5 elements)</option>
          <option>Rich (6+ elements)</option>
        </select>
      </div>
 
      <div>
        <label for="dna-size">Optical size target</label>
        <input type="text" id="dna-size" placeholder="e.g. 24 px" value="24 px">
      </div>
 
      <div class="swatch-row">
        <label>Brand palette</label>
        <div id="swatchList"></div>
        <button class="btn-sm" id="btnAddSwatch">＋</button>
      </div>
 
      <div class="dna-full">
        <label for="dna-notes">Constraints</label>
        <textarea id="dna-notes" class="dna-notes" rows="2"
          placeholder="e.g. No gradients below 16 px. Must work at 50% opacity for disabled state…"></textarea>
      </div>
 
    </div>
  </details>
</header>
 
<!-- ── MAIN ──────────────────────────────────────────────────────────────── -->
<main class="main">
  <div class="section-label">Concepts</div>
  <div class="tile-grid" id="tileGrid"></div>
</main>
 
<!-- ── BOTTOM BAR ────────────────────────────────────────────────────────── -->
<div class="bottom-bar">
  <div class="summary-line" id="summaryLine"></div>
  <button class="btn-copy" id="btnCopy">⎘ Copy note</button>
</div>
 
<div class="toast" id="toast"></div>
 
<script>
'use strict';
 
/* ── CONSTANTS ─────────────────────────────────────────────────────────── */
const STORAGE_KEY = 'icon-studio-v3';
 
const AXIS_OPTS = ['Matches', 'Minor drift', 'Major drift'];
const DRIFT_CLASS = ['ok', 'warn', 'bad'];
 
// Ten starter icons: name + a function that builds the CSS icon DOM
const STARTERS = [
  { name: 'Home',          iconFn: buildIconHome       },
  { name: 'Settings',      iconFn: buildIconSettings   },
  { name: 'Search',        iconFn: buildIconSearch     },
  { name: 'Notifications', iconFn: buildIconBell       },
  { name: 'Profile',       iconFn: buildIconUser       },
  { name: 'Bookmark',      iconFn: buildIconBookmark   },
  { name: 'Analytics',     iconFn: buildIconChart      },
  { name: 'Mail',          iconFn: buildIconMail       },
  { name: 'Calendar',      iconFn: buildIconCalendar   },
  { name: 'Lock',          iconFn: buildIconLock       },
];
 
/* ── CSS ICON BUILDERS ──────────────────────────────────────────────────── */
function el(tag, cls) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  return e;
}
 
function buildIconHome() {
  const w = el('div', 'icon icon-home');
  w.appendChild(el('div', 'door'));
  return w;
}
function buildIconSettings() {
  return el('div', 'icon icon-settings');
}
function buildIconSearch() {
  return el('div', 'icon icon-search');
}
function buildIconBell() {
  const w = el('div', 'icon icon-bell');
  w.appendChild(el('div', 'clapper'));
  return w;
}
function buildIconUser() {
  return el('div', 'icon icon-user');
}
function buildIconBookmark() {
  return el('div', 'icon icon-bookmark');
}
function buildIconChart() {
  const w = el('div', 'icon icon-chart');
  for (let i = 0; i < 4; i++) w.appendChild(el('div', 'bar'));
  return w;
}
function buildIconMail() {
  return el('div', 'icon icon-mail');
}
function buildIconCalendar() {
  return el('div', 'icon icon-calendar');
}
function buildIconLock() {
  const w = el('div', 'icon icon-lock');
  w.appendChild(el('div', 'keyhole'));
  return w;
}
 
/* ── STATE ──────────────────────────────────────────────────────────────── */
let tiles    = [];   // array of tile data objects
let swatches = [];   // array of hex strings
let nextId   = 1;
 
/* ── PERSISTENCE ────────────────────────────────────────────────────────── */
function persist() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      dna:      readDNA(),
      swatches: swatches,
      tiles:    tiles.map(function(t) {
        return { id: t.id, name: t.name, shape: t.shape,
                 color: t.color, detail: t.detail,
                 note: t.note, flagged: t.flagged };
      })
    }));
  } catch (_) {}
}
 
function loadSaved() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (_) { return null; }
}
 
/* ── DNA ────────────────────────────────────────────────────────────────── */
function readDNA() {
  return {
    shape:  document.getElementById('dna-shape').value,
    radius: document.getElementById('dna-radius').value,
    stroke: document.getElementById('dna-stroke').value,
    fill:   document.getElementById('dna-fill').value,
    detail: document.getElementById('dna-detail').value,
    size:   document.getElementById('dna-size').value,
    notes:  document.getElementById('dna-notes').value,
  };
}
 
function applyDNA(dna) {
  if (!dna) return;
  ['shape','radius','stroke','fill','detail','size','notes'].forEach(function(k) {
    const el = document.getElementById('dna-' + k);
    if (el && dna[k] !== undefined) el.value = dna[k];
  });
}
 
// Wire DNA inputs to persist
['dna-shape','dna-radius','dna-stroke','dna-fill','dna-detail','dna-size','dna-notes']
  .forEach(function(id) {
    const node = document.getElementById(id);
    if (node) node.addEventListener('input', persist);
  });
 
/* ── SWATCHES ───────────────────────────────────────────────────────────── */
document.getElementById('btnAddSwatch').addEventListener('click', function() {
  swatches.push('#1E40AF');
  renderSwatches();
  persist();
});
 
function renderSwatches() {
  const list = document.getElementById('swatchList');
  // Remove all existing swatch wrappers
  while (list.firstChild) list.removeChild(list.firstChild);
 
  swatches.forEach(function(hex, i) {
    const wrap = el('div', 'swatch-wrap');
 
    const picker = document.createElement('input');
    picker.type  = 'color';
    picker.value = hex;
    picker.addEventListener('input', function() {
      hexField.value = picker.value;
      swatches[i]    = picker.value;
      persist();
    });
 
    const hexField = document.createElement('input');
    hexField.type      = 'text';
    hexField.value     = hex;
    hexField.maxLength = 9;
    hexField.className = 'axis-sel';
    hexField.style.width = '72px';
    hexField.addEventListener('input', function() {
      if (/^#[0-9A-Fa-f]{6}$/.test(hexField.value)) {
        picker.value = hexField.value;
        swatches[i]  = hexField.value;
        persist();
      }
    });
 
    const rmBtn = el('button', 'btn-sm rm');
    rmBtn.textContent = '×';
    rmBtn.addEventListener('click', function() {
      swatches.splice(i, 1);
      renderSwatches();
      persist();
    });
 
    wrap.appendChild(picker);
    wrap.appendChild(hexField);
    wrap.appendChild(rmBtn);
    list.appendChild(wrap);
  });
}
 
/* ── TILE DATA ──────────────────────────────────────────────────────────── */
function makeTileData(overrides) {
  const d = overrides || {};
  return {
    id:      d.id      !== undefined ? d.id      : nextId++,
    name:    d.name    !== undefined ? d.name    : '',
    shape:   d.shape   !== undefined ? d.shape   : 0,
    color:   d.color   !== undefined ? d.color   : 0,
    detail:  d.detail  !== undefined ? d.detail  : 0,
    note:    d.note    !== undefined ? d.note    : '',
    flagged: d.flagged !== undefined ? d.flagged : false,
    iconIdx: d.iconIdx !== undefined ? d.iconIdx : 0,
  };
}
 
function driftClass(t) {
  if (t.flagged) return 'flagged';
  return DRIFT_CLASS[Math.max(t.shape, t.color, t.detail)];
}
 
function badgeText(t) {
  if (t.flagged)         return 'Flagged';
  const w = Math.max(t.shape, t.color, t.detail);
  return w === 0 ? 'On-spec' : w === 1 ? 'Drift' : 'Major drift';
}
 
/* ── CARD BUILD ─────────────────────────────────────────────────────────── */
function buildCard(t) {
  const dc   = driftClass(t);
  const card = el('div', 'tile-card state-' + dc);
  card.dataset.tid = t.id;
 
  /* preview */
  const preview = el('div', 'tile-preview');
 
  // look up icon builder from starters or use first as fallback
  const starter = STARTERS[t.iconIdx] || STARTERS[0];
  preview.appendChild(starter.iconFn());
 
  const driftBar = el('div', 'tile-drift-bar');
  ['shape','color','detail'].forEach(function(axis) {
    const seg = el('div', 'drift-seg ' + DRIFT_CLASS[t[axis]]);
    seg.dataset.axis = axis;
    driftBar.appendChild(seg);
  });
  preview.appendChild(driftBar);
  card.appendChild(preview);
 
  /* body */
  const body = el('div', 'tile-body');
 
  const nameInput = document.createElement('input');
  nameInput.type        = 'text';
  nameInput.className   = 'tile-name';
  nameInput.placeholder = 'Icon name…';
  nameInput.value       = t.name;
  nameInput.addEventListener('input', function() {
    t.name = nameInput.value;
    persist();
    refreshSummary();
  });
  body.appendChild(nameInput);
 
  /* three axis rows */
  [
    { key: 'shape',  label: 'Shape'  },
    { key: 'color',  label: 'Color'  },
    { key: 'detail', label: 'Detail' },
  ].forEach(function(axis) {
    const row = el('div', 'axis-row');
    const lbl = el('span', 'axis-lbl');
    lbl.textContent = axis.label;
    row.appendChild(lbl);
 
    const sel = el('select', 'axis-sel');
    AXIS_OPTS.forEach(function(optText, i) {
      const opt   = document.createElement('option');
      opt.value   = i;
      opt.textContent = optText;
      if (i === t[axis.key]) opt.selected = true;
      sel.appendChild(opt);
    });
    sel.addEventListener('change', function() {
      t[axis.key] = parseInt(sel.value, 10);
      syncCard(card, t);
      persist();
      refreshSummary();
    });
    row.appendChild(sel);
    body.appendChild(row);
  });
 
  /* observation textarea */
  const obs = el('textarea', 'tile-obs');
  obs.rows        = 2;
  obs.placeholder = 'Observation…';
  obs.textContent = t.note;
  obs.addEventListener('input', function() {
    t.note = obs.value;
    persist();
  });
  body.appendChild(obs);
 
  card.appendChild(body);
 
  /* footer */
  const footer = el('div', 'tile-footer');
 
  const badge = el('span', 'drift-badge ' + dc);
  badge.textContent = badgeText(t);
  footer.appendChild(badge);
 
  const actions = el('div', 'tile-actions');
 
  const flagBtn = el('button', 'btn-icon btn-flag' + (t.flagged ? ' active' : ''));
  flagBtn.title       = 'Flag / unflag';
  flagBtn.textContent = '⚑';
  flagBtn.addEventListener('click', function() {
    t.flagged = !t.flagged;
    syncCard(card, t);
    persist();
    refreshSummary();
  });
  actions.appendChild(flagBtn);
 
  const delBtn = el('button', 'btn-icon');
  delBtn.title       = 'Remove';
  delBtn.textContent = '✕';
  delBtn.addEventListener('click', function() {
    tiles = tiles.filter(function(x) { return x.id !== t.id; });
    card.parentNode.removeChild(card);
    persist();
    refreshSummary();
  });
  actions.appendChild(delBtn);
 
  footer.appendChild(actions);
  card.appendChild(footer);
 
  return card;
}
 
/* update an existing card's visual state without rebuilding it */
function syncCard(card, t) {
  const dc = driftClass(t);
 
  // border state
  card.className = 'tile-card state-' + dc;
 
  // drift bar segments
  card.querySelectorAll('.drift-seg').forEach(function(seg) {
    seg.className = 'drift-seg ' + DRIFT_CLASS[t[seg.dataset.axis]];
  });
 
  // badge
  const badge = card.querySelector('.drift-badge');
  badge.className   = 'drift-badge ' + dc;
  badge.textContent = badgeText(t);
 
  // flag button
  const flagBtn = card.querySelector('.btn-flag');
  if (t.flagged) {
    flagBtn.classList.add('active');
  } else {
    flagBtn.classList.remove('active');
  }
}
 
/* ── TILE GRID RENDER ───────────────────────────────────────────────────── */
function renderGrid() {
  const grid = document.getElementById('tileGrid');
 
  // Clear only tile cards, keep the add button if it exists
  grid.querySelectorAll('.tile-card').forEach(function(c) {
    grid.removeChild(c);
  });
 
  let addBtn = grid.querySelector('.btn-add-tile');
  if (!addBtn) {
    addBtn = el('button', 'btn-add-tile');
    addBtn.textContent = '＋ Add concept';
    addBtn.addEventListener('click', function() {
      const idx  = tiles.length % STARTERS.length;
      const t    = makeTileData({ iconIdx: idx });
      tiles.push(t);
      const card = buildCard(t);
      grid.insertBefore(card, addBtn);
      persist();
      refreshSummary();
    });
    grid.appendChild(addBtn);
  }
 
  tiles.forEach(function(t) {
    grid.insertBefore(buildCard(t), addBtn);
  });
 
  refreshSummary();
}
 
/* ── SUMMARY BAR ────────────────────────────────────────────────────────── */
function refreshSummary() {
  const total   = tiles.length;
  const flagged = tiles.filter(function(t) { return t.flagged; }).length;
  const bad     = tiles.filter(function(t) {
    return !t.flagged && driftClass(t) === 'bad';
  }).length;
  const warn    = tiles.filter(function(t) {
    return !t.flagged && driftClass(t) === 'warn';
  }).length;
  const ok      = total - flagged - bad - warn;
 
  const line = document.getElementById('summaryLine');
  while (line.firstChild) line.removeChild(line.firstChild);
 
  function seg(text, cls) {
    const s = el('span', cls || '');
    s.textContent = text;
    return s;
  }
  line.appendChild(seg(String(total), 's-total'));
  line.appendChild(seg(' tiles · '));
  line.appendChild(seg(String(flagged + bad) + ' ⚑', 's-bad'));
  line.appendChild(seg(' drift · '));
  line.appendChild(seg(String(warn) + ' ~', 's-warn'));
  line.appendChild(seg(' warn · '));
  line.appendChild(seg(String(ok) + ' ✓ ok'));
}
 
/* ── COPY ART DIRECTION ─────────────────────────────────────────────────── */
document.getElementById('btnCopy').addEventListener('click', function() {
  const note = buildNote();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(note).then(function() { toast('Art direction copied ✓'); });
  } else {
    const ta = document.createElement('textarea');
    ta.value = note;
    ta.style.cssText = 'position:fixed;opacity:0;top:0;left:0;';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    toast('Copied ✓');
  }
});
 
function buildNote() {
  const dna  = readDNA();
  const rows = [];
  rows.push('ICON FAMILY ART DIRECTION');
  rows.push('════════════════════════════════════════');
  rows.push('');
  rows.push('SPEC');
  rows.push('  Shape: ' + dna.shape + '  ·  Corner radius: ' + dna.radius);
  rows.push('  Stroke: ' + dna.stroke + '  ·  Fill: ' + dna.fill);
  rows.push('  Detail: ' + dna.detail + '  ·  Target size: ' + dna.size);
  if (swatches.length) {
    rows.push('  Palette: ' + swatches.join('  '));
  }
  if (dna.notes.trim()) {
    rows.push('');
    rows.push('CONSTRAINTS');
    dna.notes.split('\n').forEach(function(l) {
      if (l.trim()) rows.push('  ' + l.trim());
    });
  }
  const drifted = tiles.filter(function(t) {
    return t.flagged || driftClass(t) !== 'ok';
  });
  if (drifted.length) {
    rows.push('');
    rows.push('DRIFT FLAGS');
    drifted.forEach(function(t) {
      const axes = [];
      if (t.shape  > 0) axes.push('shape('  + AXIS_OPTS[t.shape]  + ')');
      if (t.color  > 0) axes.push('color('  + AXIS_OPTS[t.color]  + ')');
      if (t.detail > 0) axes.push('detail(' + AXIS_OPTS[t.detail] + ')');
      const label = (t.name || 'Tile ' + t.id) + (t.flagged ? ' ⚑' : '');
      rows.push('  ' + label + ': ' + (axes.join(', ') || 'manually flagged'));
      if (t.note.trim()) rows.push('    → ' + t.note.trim());
    });
  }
  const good = tiles.filter(function(t) {
    return !t.flagged && driftClass(t) === 'ok';
  });
  if (good.length) {
    rows.push('');
    rows.push('ON-SPEC');
    rows.push('  ' + good.map(function(t) { return t.name || 'Tile ' + t.id; }).join('  ·  '));
  }
  rows.push('');
  rows.push('Generated ' + new Date().toLocaleString());
  return rows.join('\n');
}
 
/* ── TOAST ──────────────────────────────────────────────────────────────── */
function toast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(function() { t.classList.remove('show'); }, 2200);
}
 
/* ── INIT ───────────────────────────────────────────────────────────────── */
(function init() {
  const saved = loadSaved();
  if (saved && saved.tiles && saved.tiles.length) {
    applyDNA(saved.dna);
    swatches = saved.swatches || ['#1E40AF','#FFFFFF','#F1F5F9'];
    renderSwatches();
    saved.tiles.forEach(function(td, i) {
      if (td.id >= nextId) nextId = td.id + 1;
      // attach icon index: use position mod starters if not stored
      td.iconIdx = (td.iconIdx !== undefined) ? td.iconIdx : (i % STARTERS.length);
      tiles.push(makeTileData(td));
    });
  } else {
    swatches = ['#1E40AF','#FFFFFF','#F1F5F9'];
    renderSwatches();
    STARTERS.forEach(function(s, i) {
      tiles.push(makeTileData({ name: s.name, iconIdx: i }));
    });
  }
  renderGrid();
  persist();
}());
</script>
</body>
